// ─── Helpers ──────────────────────────────────────────────────────────────────
function escapeHtml(s: string): string {
  return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
}

function infoRow(label: string, value: string, last = false): string {
  return `<tr><td style="padding:${last ? "10px 20px 20px" : "10px 20px 0"};"><p style="margin:0 0 3px;font-size:10px;font-weight:700;color:#4a8abf;letter-spacing:2px;text-transform:uppercase;">${label}</p><p style="margin:0;font-size:14px;color:#c8dff0;line-height:1.5;">${value}</p></td></tr>`;
}

function divider(): string {
  return `<tr><td style="padding:0 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="border-top:1px solid #1a3a5c;height:1px;line-height:1px;font-size:0;">&nbsp;</td></tr></table></td></tr>`;
}

