// ─── 3. Rapport hebdomadaire ──────────────────────────────────────────────────
export interface PageViewRow { path: string; date: string; count: number; }

export async function sendWeeklyReport(rows: PageViewRow[]): Promise<void> {
  const byPath = new Map<string, number>();
  let grandTotal = 0;
  for (const r of rows) { byPath.set(r.path, (byPath.get(r.path) ?? 0) + r.count); grandTotal += r.count; }
  const sorted = [...byPath.entries()].sort((a, b) => b[1] - a[1]);

  const today = new Date();
  const weekStart = new Date(today);
  weekStart.setDate(today.getDate() - 6);
  const fmt = (d: Date) => d.toLocaleDateString("fr-FR", { day: "2-digit", month: "long", year: "numeric" });
  const period = `${fmt(weekStart)} → ${fmt(today)}`;
  const maxCount = sorted[0]?.[1] ?? 1;

  const tableRows = sorted.map(([path, count], i) => {
    const bar = Math.round((count / maxCount) * 100);
    const bg = i % 2 === 0 ? "#071628" : "#0a1f3d";
    return `<tr style="background:${bg};"><td style="padding:10px 16px;font-size:12px;color:#c8dff0;font-family:monospace;">${escapeHtml(path)}</td><td style="padding:10px 16px;width:120px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="background:#1a3a5c;border-radius:2px;height:6px;padding:0;"><div style="background:linear-gradient(90deg,#1a4a8a,#2d7fd8);width:${bar}%;height:6px;border-radius:2px;min-width:4px;"></div></td></tr></table></td><td style="padding:10px 16px;font-size:13px;font-weight:700;color:#2d7fd8;text-align:right;">${count.toLocaleString("fr-FR")}</td></tr>`;
  }).join("") || `<tr><td colspan="3" style="padding:28px;text-align:center;color:#4a8abf;font-size:13px;">Aucune visite enregistrée cette semaine.</td></tr>`;

  const content = `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 28px;">
      <tr>
        <td style="vertical-align:middle;">
          <h1 style="margin:0 0 4px;font-size:22px;font-weight:900;color:#ffffff;">Rapport de trafic</h1>
          <p style="margin:0;font-size:13px;color:#4a8abf;">${period}</p>
        </td>
        <td style="text-align:right;vertical-align:middle;">
          <div style="display:inline-block;background:#071628;border:1px solid #1a3a5c;border-radius:8px;padding:12px 20px;text-align:center;">
            <p style="margin:0 0 2px;font-size:28px;font-weight:900;color:#2d7fd8;">${grandTotal.toLocaleString("fr-FR")}</p>
            <p style="margin:0;font-size:10px;color:#4a8abf;letter-spacing:2px;text-transform:uppercase;">Visites</p>
          </div>
        </td>
      </tr>
    </table>

    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #1a3a5c;border-radius:6px;overflow:hidden;margin:0 0 24px;">
      <thead>
        <tr style="background:#0d2242;">
          <th style="padding:10px 16px;font-size:10px;font-weight:700;color:#4a8abf;letter-spacing:2px;text-transform:uppercase;text-align:left;">Page</th>
          <th style="padding:10px 16px;width:120px;"></th>
          <th style="padding:10px 16px;font-size:10px;font-weight:700;color:#4a8abf;letter-spacing:2px;text-transform:uppercase;text-align:right;">Vues</th>
        </tr>
      </thead>
      <tbody>
        ${tableRows}
        <tr style="background:#0d2242;border-top:2px solid #1a4a8a;">
          <td colspan="2" style="padding:12px 16px;font-size:13px;font-weight:700;color:#ffffff;">Total de la semaine</td>
          <td style="padding:12px 16px;font-size:16px;font-weight:900;color:#2d7fd8;text-align:right;">${grandTotal.toLocaleString("fr-FR")}</td>
        </tr>
      </tbody>
    </table>

    <p style="margin:0;font-size:12px;color:#4a8abf;line-height:1.6;">
      Rapport automatique envoyé chaque <strong style="color:#8ab0d0;">mercredi à 16h</strong>.<br/>
      Tracking anonyme de navigation sur mvprotect.fr.
    </p>
  `;

  await send({
    to: OWNER_EMAIL,
    subject: `📊 Trafic semaine — ${grandTotal.toLocaleString("fr-FR")} visites — ${period}`,
    html: wrapInTemplate(content, "Rapport hebdomadaire"),
  });
}

// ─── Fire-and-forget ──────────────────────────────────────────────────────────
export function fireEmail(fn: () => Promise<void>, context: string): void {
  fn().catch((err: unknown) => { logger.error({ err, context }, "Email sending failed"); });
}
